/**
 * Where each surface is installed from. These are the stores' and the
 * site's public addresses, not settings: nothing on the server knows them,
 * the app has to name them to send anybody there, and they move only if a
 * store listing or the site does. Each carries `ref`, so a visit from the
 * app can be told apart from any other on the site's own page counts.
 *
 * Whether a surface may be offered at all is not decided here: that is the
 * server's `release` for it (the cross_promotion flag), so the Android link
 * appears the day an operator marks the app live, without a release of this
 * one.
 */

/** The browser extension's listings: the public pages, no locale, no account parameters. */
export const EXTENSION_STORES = {
  chrome: 'https://chromewebstore.google.com/detail/cmadljhpbngcceagpjfladgjjjnegikk',
  firefox: 'https://addons.mozilla.org/firefox/addon/lexpad/',
} as const;

/** The site's page about the extension, which links both stores: what a phone sends to a computer. */
export const EXTENSION_PAGE_URL = 'https://lexpad.app/features/extension';

/** The desktop app's page and downloads (macOS and Windows), on the site. */
export const DESKTOP_PAGE_URL = 'https://lexpad.app/features/desktop';

/** The Android app on Google Play (package app.lexpad.android). */
export const PLAY_URL = 'https://play.google.com/store/apps/details?id=app.lexpad.android';

/** Adds the place in the app a link was opened from, for the site's and stores' own counts. */
export function withRef(url: string, ref: string): string {
  const parsed = new URL(url);
  parsed.searchParams.set('ref', ref);
  return parsed.href;
}

/** The study's names for the cards (N1–N8), carried as `ref` on every link a card opens. */
export const NUDGE_REF = {
  extension: 'N1',
  desktop_safari: 'N2',
  desktop_power: 'N3',
  on_your_computer: 'N4',
  on_your_phone: 'N5',
  android_browser: 'N6',
  connector: 'N7',
  kindle: 'N8',
} as const;
