/**
 * The two SRS v2 offers Today may make, each at the one moment it helps
 * (SRS v2 access proposals 3 and 8), all of it read locally:
 *
 * - the Smart invitation: one quiet card, once, for a learner whose
 *   notebook has enough history for Smart to work from;
 * - the daily-limit line: after a few days away with a big backlog, the day's
 *   card offers to set a daily review limit, once per break.
 *
 * Both stay silent unless the server switched their feature on, so with the
 * flag off Today reads nothing more than it did.
 */
import type { Word } from '@lexpad/core';
import { listWords, loadSchedule, loadStreak } from '@/db/repo.js';
import { db, getMeta, setMeta, type StoredNotebook } from '@/db/schema.js';
import { loadSrsView, shows } from '@/features/schedule/data.js';

/**
 * Practice days (days with at least one answer) before Smart is offered: two
 * weeks of answers is what the spec's Smart needs to have something to work
 * from (access proposal 3). A product threshold for an in-app hint, not a
 * limit the server enforces, so it lives here beside the rule it shapes.
 */
export const SMART_INVITE_DAYS = 14;

/** Words in the notebook answered at least once before Smart is offered (same reason). */
export const SMART_INVITE_WORDS = 50;

/** Days without an answer that make a return a comeback (access proposal 8). */
export const COMEBACK_DAYS = 3;

/**
 * Reviews due in the notebook above which a comeback is a backlog worth a
 * daily limit (access proposal 8). The learner's own number decides the
 * limit; this only decides when to mention that one exists.
 */
export const BACKLOG_DUE = 100;

/** What Today offers about SRS v2, beyond what it always shows. */
export interface SrsOffers {
  /** The one-time card introducing Smart. */
  smartInvite: boolean;
  /**
   * The daily-limit line: the last day practised before this break, which
   * is also what putting it away remembers, or undefined for no line.
   */
  capOffer: number | undefined;
}

export const NO_OFFERS: SrsOffers = { smartInvite: false, capOffer: undefined };

/**
 * Works out both offers for the notebook in view. The cheap facts are read
 * first and the notebook's words only when everything else already holds,
 * so on most days this costs a few meta reads.
 */
export async function loadSrsOffers(
  notebook: StoredNotebook | undefined,
  today: number,
  /**
   * The notebook's words started and due today, when the caller has just
   * counted them (Today, showing this one notebook): then its words are not
   * read a second time.
   */
  counted?: { started: number; due: number },
): Promise<SrsOffers> {
  if (notebook === undefined) return NO_OFFERS;
  const srs = await loadSrsView();
  const wantsSmart = shows(srs, 'smart');
  const wantsCap = shows(srs, 'reviewCap');
  if (!wantsSmart && !wantsCap) return NO_OFFERS;

  const [schedule, inviteSeen, introSeen, streak, dismissed] = await Promise.all([
    loadSchedule(notebook.id),
    getMeta('smartInviteSeen'),
    getMeta('smartIntroSeen'),
    loadStreak(),
    getMeta('capOfferDismissed'),
  ]);

  // Smart: offered once, to a Boxes notebook, never after either card was put away.
  let smartInvite = wantsSmart && schedule.scheduler === 'boxes' && !inviteSeen && !introSeen;
  if (smartInvite) {
    const days = await db.dayStats.filter((stat) => stat.reviewed > 0).count();
    smartInvite = days >= SMART_INVITE_DAYS;
  }

  // The daily limit: a comeback, no limit set, and this break's offer not yet put away.
  let capOffer: number | undefined;
  if (wantsCap && schedule.reviewCap === 0) {
    const last = await lastPractised(streak.lastActiveDay);
    if (last !== undefined && today - last >= COMEBACK_DAYS && dismissed !== last) capOffer = last;
  }

  if (!smartInvite && capOffer === undefined) return NO_OFFERS;
  const { started, due } = counted ?? countOf(await listWords(notebook.id), today);
  if (started < SMART_INVITE_WORDS) smartInvite = false;
  if (due <= BACKLOG_DUE) capOffer = undefined;
  return { smartInvite, capOffer };
}

/**
 * Whether a notebook has the history Smart needs to work from: the same
 * gate as the Today invitation (SMART_INVITE_DAYS practice days and
 * SMART_INVITE_WORDS words started). The schedule page's own "New: Smart
 * schedule" card waits for it too (the new learner's journey, C4), so a
 * learner on day one is never invited to change a schedule they have not
 * used yet.
 */
export async function smartHistoryReady(notebookId: string, today: number): Promise<boolean> {
  const days = await db.dayStats.filter((stat) => stat.reviewed > 0).count();
  if (days < SMART_INVITE_DAYS) return false;
  return countOf(await listWords(notebookId), today).started >= SMART_INVITE_WORDS;
}

/** Words answered at least once, and words due today (not retired). */
function countOf(words: readonly Word[], today: number): { started: number; due: number } {
  let started = 0;
  let due = 0;
  for (const word of words) {
    const progress = word.progress;
    if (progress === undefined) continue;
    if (progress.reps > 0) started += 1;
    if (!progress.retired && progress.dueDay <= today) due += 1;
  }
  return { started, due };
}

/**
 * The last day with an answer: the streak's, or, on a device that has not
 * answered yet (the streak a snapshot gives keeps no day unless it is
 * today's), the newest day of the practice history.
 */
async function lastPractised(streakDay: number | undefined): Promise<number | undefined> {
  const latest = await db.dayStats
    .orderBy('day')
    .reverse()
    .filter((stat) => stat.reviewed > 0)
    .first();
  if (latest === undefined) return streakDay;
  return streakDay === undefined ? latest.day : Math.max(streakDay, latest.day);
}

/**
 * "See how it works" or "Not now" on the Smart card: either way it is not
 * shown again. Seeing how it works also puts away the schedule page's own
 * "New: Smart schedule" card, which would say the same thing twice.
 */
export async function putSmartInviteAway(seeing = false): Promise<void> {
  await setMeta('smartInviteSeen', true);
  if (seeing) await setMeta('smartIntroSeen', true);
}

/** The daily-limit line was tapped or put away: not again until the next break. */
export async function putCapOfferAway(lastActiveDay: number): Promise<void> {
  await setMeta('capOfferDismissed', lastActiveDay);
}
